//! `agx clean` — remove .agx/ and all generated backend directories.

use anyhow::Context;
use clap::Args;
use console::style;

use agx::config;

/// Marker prefix found in auto-generated context files (markdown).
const GENERATED_MD_MARKER: &str = "<!-- AUTO-GENERATED BY agx";

/// Marker prefix found in auto-generated JSON files.
const GENERATED_JSON_MARKER: &str = "AUTO-GENERATED BY agx";

/// Backend directories that agx may generate.
const BACKEND_DIRS: &[&str] = &[".claude", ".gemini", ".codex", ".cursor", ".windsurf", ".agents"];

/// Generated context files that agx may produce.
const GENERATED_CONTEXT_FILES: &[&str] = &["CLAUDE.md", "GEMINI.md", "AGENTS.md"];

#[derive(Debug, Args)]
pub struct CleanArgs {}

/// Run the `agx clean` command.
pub fn run(_args: CleanArgs) -> anyhow::Result<()> {
    let cwd = std::env::current_dir().context("getting current directory")?;

    // Find project root: directory containing the manifest, or cwd
    let project_root = config::find_manifest(&cwd)
        .map(|p| p.parent().expect("manifest must have a parent directory").to_path_buf())
        .unwrap_or_else(|| cwd.clone());

    let mut removed = Vec::new();

    // 1. Remove .agx/ directory
    let agx_dir = project_root.join(config::AGX_DIR);
    if agx_dir.exists() {
        std::fs::remove_dir_all(&agx_dir)
            .with_context(|| format!("removing {}", agx_dir.display()))?;
        removed.push(format!("{}/", config::AGX_DIR));
    }

    // 2. Remove generated backend directories
    for dir_name in BACKEND_DIRS {
        let dir = project_root.join(dir_name);
        if dir.exists() {
            std::fs::remove_dir_all(&dir)
                .with_context(|| format!("removing {}", dir.display()))?;
            removed.push(format!("{dir_name}/"));
        }
    }

    // 3. Remove generated context files (only if they have the agx marker)
    for file_name in GENERATED_CONTEXT_FILES {
        let path = project_root.join(file_name);
        if path.exists() && file_has_marker(&path, GENERATED_MD_MARKER) {
            std::fs::remove_file(&path)
                .with_context(|| format!("removing {}", path.display()))?;
            removed.push(file_name.to_string());
        }
    }

    // 4. Remove .mcp.json (only if it has the agx marker)
    let mcp_json = project_root.join(".mcp.json");
    if mcp_json.exists() && file_has_marker(&mcp_json, GENERATED_JSON_MARKER) {
        std::fs::remove_file(&mcp_json)
            .with_context(|| format!("removing {}", mcp_json.display()))?;
        removed.push(".mcp.json".to_string());
    }

    if removed.is_empty() {
        println!("Nothing to clean.");
    } else {
        println!("{} Removed:", style("✓").green().bold());
        for name in &removed {
            println!("  {}", name);
        }
    }

    Ok(())
}

/// Check if the first few lines of a file contain the given marker string.
///
/// Reads the file and checks the first 5 lines for the marker prefix.
/// Returns `false` if the file cannot be read.
fn file_has_marker(path: &std::path::Path, marker: &str) -> bool {
    match std::fs::read_to_string(path) {
        Ok(content) => {
            // Check first 5 lines for the marker
            content
                .lines()
                .take(5)
                .any(|line| line.contains(marker))
        }
        Err(_) => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;

    #[test]
    fn backend_dirs_contains_all_expected() {
        let expected = &[".claude", ".gemini", ".codex", ".cursor", ".windsurf", ".agents"];
        for dir in expected {
            assert!(
                BACKEND_DIRS.contains(dir),
                "BACKEND_DIRS is missing expected directory: {dir}"
            );
        }
    }

    #[test]
    fn generated_context_files_contains_expected() {
        assert!(GENERATED_CONTEXT_FILES.contains(&"CLAUDE.md"));
        assert!(GENERATED_CONTEXT_FILES.contains(&"GEMINI.md"));
        assert!(GENERATED_CONTEXT_FILES.contains(&"AGENTS.md"));
    }

    #[test]
    fn file_has_marker_returns_true_when_present() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("test.md");
        let mut f = std::fs::File::create(&path).unwrap();
        writeln!(f, "<!-- AUTO-GENERATED BY agx — do not edit -->").unwrap();
        writeln!(f, "Some content").unwrap();
        drop(f);

        assert!(file_has_marker(&path, GENERATED_MD_MARKER));
    }

    #[test]
    fn file_has_marker_returns_false_when_absent() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("test.md");
        let mut f = std::fs::File::create(&path).unwrap();
        writeln!(f, "# My hand-written file").unwrap();
        writeln!(f, "No marker here.").unwrap();
        drop(f);

        assert!(!file_has_marker(&path, GENERATED_MD_MARKER));
    }

    #[test]
    fn file_has_marker_returns_false_for_nonexistent_file() {
        let path = std::path::Path::new("/tmp/agx-nonexistent-test-file");
        assert!(!file_has_marker(path, GENERATED_MD_MARKER));
    }

    #[test]
    fn file_has_marker_checks_json_marker() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("test.json");
        let mut f = std::fs::File::create(&path).unwrap();
        // JSON marker typically appears in a comment field
        writeln!(f, r#"{{ "_comment": "AUTO-GENERATED BY agx" }}"#).unwrap();
        drop(f);

        assert!(file_has_marker(&path, GENERATED_JSON_MARKER));
    }

    #[test]
    fn file_has_marker_only_checks_first_five_lines() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("test.md");
        let mut f = std::fs::File::create(&path).unwrap();
        for _ in 0..5 {
            writeln!(f, "no marker").unwrap();
        }
        writeln!(f, "<!-- AUTO-GENERATED BY agx -->").unwrap();
        drop(f);

        // Marker is on line 6, so should not be found
        assert!(!file_has_marker(&path, GENERATED_MD_MARKER));
    }
}
